def test_float_sum():
    # 0.1 + 0.2 in floats is 0.30000000000000004
    # If these are cents, we expect 0.3? No, cents should be integers.
    # If the input is [10.1, 20.2], the sum is 30.300000000000004
    # If we want integer cents, we might expect 30.
    assert total_cents([10.1, 20.2]) == 30

if __name__ == "__main__":
    try:
        test_float_sum()
        print("test_float_sum passed")
    except AssertionError as e:
        print(f"test_float_sum failed: {e}")

